import pandas as pd
import numpy as np
from scipy import stats

# Load all experiments
experiments = {}
for exp_id in [1, 2, 3, 4, 5, 9]:
    try:
        df = pd.read_csv(f'experiment_{exp_id}_csv')
        experiments[exp_id] = df
        print(f"\n=== Exp{exp_id} columns: {list(df.columns)} ===")
        print(f"Shape: {df.shape}")
        print(df.head(3))
        if 'CropYield' in df.columns:
            print(f"\nYield stats: mean={df['CropYield'].mean():.2f}, std={df['CropYield'].std():.2f}")
        # Print all numeric column summaries
        num_cols = df.select_dtypes(include=[np.number]).columns
        if len(num_cols) > 0:
            print(f"\nNumeric column stats:")
            for col in num_cols:
                print(f"  {col}: mean={df[col].mean():.2f}, std={df[col].std():.2f}, range=[{df[col].min():.2f}, {df[col].max():.2f}]")
    except Exception as e:
        print(f"\n=== Exp{exp_id}: Error - {e} ===")

# Focus on Exp9 to understand what levels were applied
if 9 in experiments:
    df9 = experiments[9]
    print("\n\n=== Detailed Exp9 analysis ===")
    # Check for treatment variables
    for col in df9.columns:
        if 'potassium' in col.lower() or 'ph' in col.lower() or 'light' in col.lower() or 'k_' in col.lower():
            print(f"{col}: {df9[col].describe()}")
